474	        List<String> missingFields = RequiredOwnerFields.missingFields(ownerFieldsDto);
475	        if (!missingFields.isEmpty()) {
476	            throw new MissingRequiredFieldsException(missingFields);
477	        }
478	        OwnerPostcode.validate(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
479	        OwnerRegistrationDate.validate(ownerFieldsDto.getRegistrationDate());
480	        HttpHeaders headers = new HttpHeaders();
481	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
482	        owner.setTelephone(OwnerTelephone.normalize(ownerFieldsDto.getTelephone()));
483	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
484	        owner.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
485	        // Joining a household assigns the householdId that is part of the identity key; this
486	        // method is transactional, so a later rejection rolls the household change back.
487	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
488	            this.clinicService.joinHousehold(owner);
489	        }
490	        if (this.clinicService.ownerIdentityKeyExists(owner)) {
491	            throw new DuplicateIdentityException(owner.getIdentityKey());
492	        }
493	        if (this.clinicService.countOwnersInCity(ownerFieldsDto.getCity()) >= CITY_CAPACITY) {
494	            throw new CityCapacityExceededException(ownerFieldsDto.getCity(), CITY_CAPACITY);
495	        }
496	        LocalDate registrationDate = BusinessDays.rollForward(
497	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
498	        long ownersCreatedToday = this.clinicService.countOwnersRegisteredOn(registrationDate);
499	        if (ownersCreatedToday >= DAILY_OWNER_LIMIT) {
500	            throw new DailyOwnerLimitExceededException(DAILY_OWNER_LIMIT);
501	        }
