503	        owner.setBulkSignupWarning(ownersCreatedToday > BULK_SIGNUP_THRESHOLD);
504	        this.clinicService.saveOwner(owner);
505	        AUDIT.info("Owner created: id={}, customerCode={}, region={}, membershipNumber={}, checkDigit={}, "
506	                + "registrationDate={}, membershipLevel={}",
507	            owner.getId(), owner.getCustomerCode(), ownerMapper.toLocality(owner),
508	            ownerMapper.toMembershipNumber(owner), ownerMapper.toCheckDigit(owner),
509	            owner.getRegistrationDate(), ownerMapper.toMembershipLevel(owner));
510	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
511	        headers.setLocation(UriComponentsBuilder.newInstance()
512	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
513	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
514	    }
